interface.definition:
a!localVariables(
  local!pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: 10,
    sort: {
      #"SYSTEM_SYSRULES_sortInfo"(
        field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/331a1fda-174e-4caf-976e-0e259856800f",
        ascending: false
      )
    }
  ),
  /* Paridad SCA (Cancelar en Alta limpia la búsqueda): los filtros se reinician al cambiar de vista */
  local!fPoliza: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  /* Paridad SCA_BuscarSolicitudClientePoliza: validación de la póliza tecleada (existe y es anulable por SCA) */
  local!polizaDetailsBusq: if(
    or(
      a!isNullOrEmpty(local!fPoliza),
      regexmatch("[a-zA-Z]+", local!fPoliza)
    ),
    null,
    reduce(
      index(_, _, null),
      #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20052562"(
        {
          pcodcia: 41,
          pnumpoliza: local!fPoliza,
          pnumapli: 0,
          pnumsptoapli: 0,
          pmcaconsultaglobal: "S",
          pmcalk: "S"
        }
      ),
      {
        "MSSPObtenerPolizaFecha",
        "poconpolizat",
        "array",
        1,
        "datosgeneralespol",
        "array",
        1
      }
    )
  ),
  local!tipoPolizaBusq: if(
    a!isNullOrEmpty(local!polizaDetailsBusq),
    null,
    #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20052969"(numPoliza: local!fPoliza)
  ),
  local!codRamoBusq: if(
    a!isNotNullOrEmpty(local!polizaDetailsBusq),
    index(
      local!polizaDetailsBusq,
      "codproducto",
      "000"
    ),
    "000"
  ),
  local!errorPolizaBusq: if(
    a!isNullOrEmpty(local!fPoliza),
    null,
    if(
      regexmatch("[a-zA-Z]+", local!fPoliza),
      "El formato de la póliza no es el esperado",
      if(
        or(
          a!isNullOrEmpty(local!polizaDetailsBusq),
          and(
            local!tipoPolizaBusq <> "wAutemis",
            local!codRamoBusq <> "210",
            local!codRamoBusq <> "200",
            local!codRamoBusq <> "73"
          )
        ),
        "La póliza no es una póliza válida o no se encuentra disponible, por lo tanto, no se puede gestionar la anulación por SCA.",
        null
      )
    )
  ),
  /* Con póliza inválida no se filtra: se conserva la tabla de últimas solicitudes, como SCA */
  local!fPolizaBusq: if(
    a!isNullOrEmpty(local!errorPolizaBusq),
    local!fPoliza,
    null
  ),
  local!fSolicitud: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fNombre: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fApe1: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fApe2: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fTipoDoc: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fNumDoc: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!eleccionPoliza: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fEstado: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fLineaNegocio: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fMatricula: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!fBastidor: a!refreshVariable(value: null, refreshOnVarChange: ri!vista),
  local!seleccionado: 1,
  /* vista: BUSQUEDA / POPUP / ALTA / DETALLE (port de SCA_BuscadorSolicitudPrincipalEstrategicas)
     Persistida en la URL del site vía ri!vista/ri!numPoliza/ri!idSolicitud/ri!tipoAccion/ri!idTarea */
  local!vista: a!defaultValue(ri!vista, "BUSQUEDA"),
  local!mensajeAlta: null,
  /* Matrícula / bastidor -> lista de pólizas (buscarMatricula) */
  local!polizasMatricula: if(
    and(
      a!isNullOrEmpty(local!fMatricula),
      a!isNullOrEmpty(local!fBastidor)
    ),
    null,
    index(
      #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050966"(
        bastidor: local!fBastidor,
        matricula: local!fMatricula
      ),
      "MSSBuscarMatricula",
      "RESP_EXT_GEST_DOC",
      "LISTA_POLIZAS",
      null
    )
  ),
  /* Búsqueda por cliente (paridad SCA_BuscarSolicitudClientePoliza): consultarDP por tipo+nº documento o por
     nombre+apellido1 -> dpersonal[].COD_INT -> consultarSolicitudes (tpBusqueda 1) por cada tercero */
  local!buscaCliente: and(
    local!seleccionado = 1,
    or(
      and(
        a!isNotNullOrEmpty(local!fTipoDoc),
        a!isNotNullOrEmpty(local!fNumDoc)
      ),
      and(
        a!isNotNullOrEmpty(local!fNombre),
        a!isNotNullOrEmpty(local!fApe1)
      )
    )
  ),
  local!detallesPersonales: if(
    not(local!buscaCliente),
    null,
    if(
      and(
        a!isNotNullOrEmpty(local!fTipoDoc),
        a!isNotNullOrEmpty(local!fNumDoc)
      ),
      #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20052605"(
        MSEconsultarDP: 'type!{http://ARQ_DatTercero_SLIB/PARAMETROS_ACTDIR/4_0_0}PARAMETROS_CONDP_DPER'(
          p_cod_docum: upper(trim(local!fNumDoc)),
          p_tip_docum: local!fTipoDoc,
          p_cod_cia: 1,
          p_mca_lk: "N",
          p_cod_idioma: "es_ES",
          p_rows: 100,
          p_mca_potencial: "N",
          p_cabecera: "N",
          p_cod_act_tercero: 1,
          p_mca_temporal: "N",
          p_cod_act_tercero_acceso: 1
        )
      ),
      #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20052605"(
        MSEconsultarDP: 'type!{http://ARQ_DatTercero_SLIB/PARAMETROS_ACTDIR/4_0_0}PARAMETROS_CONDP_DPER'(
          p_nom_tercero: local!fNombre,
          p_ape1_tercero: local!fApe1,
          p_ape2_tercero: local!fApe2,
          p_cod_cia: 1,
          p_mca_lk: "N",
          p_cod_idioma: "es_ES",
          p_rows: 100,
          p_mca_potencial: "N",
          p_cabecera: "N",
          p_cod_act_tercero: 1,
          p_mca_temporal: "N",
          p_cod_act_tercero_acceso: 1
        )
      )
    )
  ),
  local!codsCliente: #"SYSTEM_SYSRULES_forEach"(
    items: a!flatten(
      a!defaultValue(
        index(
          index(
            local!detallesPersonales,
            "MSSconsultarDP",
            null
          ),
          "dpersonal",
          null
        ),
        {}
      )
    ),
    expression: tostring(
      a!defaultValue(index(fv!item, "COD_INT", null), "")
    )
  ),
  local!solsCliente: if(
    a!isNullOrEmpty(local!codsCliente),
    {},
    a!flatten(
      #"SYSTEM_SYSRULES_forEach"(
        items: local!codsCliente,
        expression: a!flatten(
          a!defaultValue(
            index(
              #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050936"(
                numPoliza: "",
                codInt: fv!item,
                tpBusqueda: "1"
              ),
              "MSSConsultarSolicitudes",
              null
            ),
            {}
          )
        )
      )
    )
  ),
  local!polizasCliente: #"SYSTEM_SYSRULES_forEach"(
    items: a!flatten(local!solsCliente),
    expression: tostring(
      a!defaultValue(
        index(
          fv!item,
          "numPoliza",
          index(fv!item, "numPolizaDTO", null)
        ),
        ""
      )
    )
  ),
  /* Paridad SCA_BuscarSolicitudClientePoliza: CORE devuelve también las solicitudes históricas y las creadas en SCA */
  local!solsCore: if(
    a!isNotNullOrEmpty(local!fPolizaBusq),
    a!flatten(
      index(
        #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050936"(
          numPoliza: local!fPolizaBusq,
          codInt: "",
          tpBusqueda: "0"
        ),
        "MSSConsultarSolicitudes",
        {}
      )
    ),
    if(
      a!isNotNullOrEmpty(local!codsCliente),
      a!flatten(local!solsCliente),
      {}
    )
  ),
  local!dummy,
  local!q: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:c531595c-c3b5-454c-a355-8145e7e27e9a",
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        /* Solicitudes sin idSolicitud de Core7 (PDTE-*) solo se ven en la bandeja de Errores */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
          operator: "not starts with",
          value: "PDTE-"
        ),
        if(
          a!isNullOrEmpty(local!fPolizaBusq),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b",
            operator: "=",
            value: local!fPolizaBusq
          )
        ),
        if(
          a!isNullOrEmpty(local!fSolicitud),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
            operator: "=",
            value: local!fSolicitud
          )
        ),
        if(
          a!isNullOrEmpty(local!fEstado),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          /* Paridad SCA_D_EstadosFinalesBuscador: cada opción del desplegable agrupa varios estados internos SCA2 */
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/65f4378b-cf90-4761-b1d0-16ace177a82c",
            operator: "in",
            value: a!flatten(
              #"SYSTEM_SYSRULES_forEach"(
                items: local!fEstado,
                expression: a!match(
                  value: tostring(fv!item),
                  equals: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624233",
                  then: {
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624233",
                    "EN_PROCESO",
                    "PDTE",
                    "ALTA",
                    "DECIDIDA",
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5623992",
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624004",
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5623998"
                  },
                  equals: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624010",
                  then: {
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624010",
                    "PENDIENTE_AUTORIZACION_ANULACION"
                  },
                  equals: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624034",
                  then: {
                    #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624034",
                    "RECHAZADA",
                    "ERROR"
                  },
                  equals: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624046",
                  then: { #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624046", #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624052" },
                  default: tostring(fv!item)
                )
              )
            )
          )
        ),
        if(
          a!isNullOrEmpty(local!fLineaNegocio),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/2242a3b0-3166-45d7-91fc-3082f21a1a34",
            operator: "=",
            value: local!fLineaNegocio
          )
        ),
        if(
          not(local!buscaCliente),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          /* Cliente sin solicitudes en CORE: ningún resultado (el operador "in" no admite lista vacía) */
          if(
            a!isNullOrEmpty(local!polizasCliente),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
              operator: "<",
              value: 0
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b",
              operator: "in",
              value: local!polizasCliente
            )
          )
        ),
        if(
          and(
            a!isNullOrEmpty(local!fMatricula),
            a!isNullOrEmpty(local!fBastidor)
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
            operator: ">",
            value: 0
          ),
          if(
            a!isNullOrEmpty(local!polizasMatricula),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
              operator: "<",
              value: 0
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b",
              operator: "in",
              value: local!polizasMatricula
            )
          )
        )
      }
    ),
    fields: {
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/11313fc1-239e-4e39-9a00-d8494bcd63c2",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/65f4378b-cf90-4761-b1d0-16ace177a82c",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/2242a3b0-3166-45d7-91fc-3082f21a1a34",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/331a1fda-174e-4caf-976e-0e259856800f",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/022e0915-97a9-4742-b07f-1361765eee72",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/074b8e94-466e-4e45-8fed-074610396bed",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/63161335-1bdd-4c7a-82eb-3560786a41d5/b3b05401-6420-4d28-8c0a-d55c0665a687",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/63161335-1bdd-4c7a-82eb-3560786a41d5/d3ea438a-426e-4524-b46c-052fb101097d",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/63161335-1bdd-4c7a-82eb-3560786a41d5/78fc061f-12bd-441e-aa55-dcff066af9fe",
      #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/63161335-1bdd-4c7a-82eb-3560786a41d5/ef1b0aa7-41ee-4590-83b2-52f89c8be7f5"
    },
    pagingInfo: local!pagingInfo,
    fetchTotalCount: true
  ),
  local!idsSca2: touniformstring(
    #"SYSTEM_SYSRULES_forEach"(
      items: index(local!q, "data", {}),
      expression: tostring(
        index(
          fv!item,
          #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
          ""
        )
      )
    )
  ),
  local!solsCoreOtras: a!localVariables(
    local!idx: where(
      #"SYSTEM_SYSRULES_forEach"(
        items: local!solsCore,
        expression: not(
          contains(
            local!idsSca2,
            tostring(index(fv!item, "idSolicitud", ""))
          )
        )
      )
    ),
    if(
      a!isNullOrEmpty(local!idx),
      {},
      index(local!solsCore, local!idx, {})
    )
  ),
  {
    if(
      local!vista = "POPUP",
      #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20064994"(
        poliza: ri!numPoliza,
        vista: ri!vista,
        polizaAlta: ri!numPoliza,
        idSolicitud: ri!idSolicitud
      ),
      if(
        local!vista = "ALTA",
        #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20055716"(
          numPoliza: ri!numPoliza,
          vista: ri!vista,
          idSolicitudSel: ri!idSolicitud,
          tipoAccion: ri!tipoAccion,
          idTarea: ri!idTarea
        ),
        if(
          a!isNotNullOrEmpty(ri!idSolicitud),
          #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20055572"(
            idSolicitud: ri!idSolicitud,
            idSel: ri!idSolicitud,
            tipoAccion: ri!tipoAccion,
            idTarea: ri!idTarea,
            numPoliza: ri!numPoliza
          ),
          {
            if(
              a!isNotNullOrEmpty(local!mensajeAlta),
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextIcon"(icon: "check-circle", color: "POSITIVE")
                      ),
                      width: "MINIMIZE"
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: local!mensajeAlta,
                          color: "POSITIVE"
                        )
                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "times",
                          link: #"SYSTEM_SYSRULES_dynamicLink"(
                            saveInto: a!save(local!mensajeAlta, null)
                          ),
                          color: "SECONDARY",
                          linkStyle: "STANDALONE"
                        )
                      ),
                      width: "MINIMIZE"
                    )
                  },
                  alignVertical: "MIDDLE"
                ),
                marginBelow: "STANDARD",
                style: "SUCCESS",
                shape: "ROUNDED"
              ),
              {}
            ),
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: "Buscar solicitud por",
                            size: "MEDIUM",
                            color: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624178",
                            style: "STRONG",
                            linkStyle: "STANDALONE"
                          )
                        )
                      },
                      width: "NARROW"
                    ),
                    #"SYSTEM_SYSRULES_forEach"(
                      items: { "Cliente", "Póliza" },
                      expression: #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_columnsLayout"(
                            columns: {
                              #"SYSTEM_SYSRULES_columnLayout"(
                                contents: {
